class Getter:
 def __call__(self,obj): raise RuntimeError("call")
 def __getattribute__(self,name):
  if name=="__name__" or name=="__isabstractmethod__": raise RuntimeError("metadata")
  return object.__getattribute__(self,name)
item=property(Getter(),doc="fixed")
print(len(dir(type(item))),"fget" in type.__dir__(type(item)))

class Descriptor:
 def __get__(self,obj,owner): raise RuntimeError("bind")
class A: entry=Descriptor()
item=A.__dict__
print(len(dir(type(item))),"entry" in dir(type(item)),"entry" in A.__dict__)

class Key:
 def __hash__(self): return hash("__call__")
 def __eq__(self,other):
  raise ValueError("collision")
key=Key()
class A:
 @property
 def __class__(self): return type(object.__dir__)
a=A()
a.__dict__[key]=7
print("before")
object.__dir__(a)
